// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.database.daoimport androidx.room.Daoimport androidx.room.Insertimport androidx.room.OnConflictStrategyimport androidx.room.Queryimport com.roshan.persona.database.entity.SemanticFactEntity@Daointerface SemanticFactDao {    @Insert(onConflict = OnConflictStrategy.REPLACE)    suspend fun insert(entity: SemanticFactEntity): Long    @Query("SELECT * FROM semantic_facts WHERE id = :id AND is_deleted = 0")    suspend fun getById(id: Long): SemanticFactEntity?    @Query("SELECT * FROM semantic_facts WHERE subject_entity_id = :entityId AND is_deleted = 0 AND valid_to IS NULL")    suspend fun getForSubject(entityId: Long): List<SemanticFactEntity>    @Query("SELECT * FROM semantic_facts WHERE predicate = :predicate AND is_deleted = 0 AND valid_to IS NULL")    suspend fun getByPredicate(predicate: String): List<SemanticFactEntity>    @Query("UPDATE semantic_facts SET confidence_alpha = confidence_alpha + 1 WHERE id = :id")    suspend fun reinforce(id: Long)    @Query("UPDATE semantic_facts SET confidence_beta = confidence_beta + 1 WHERE id = :id")    suspend fun contradict(id: Long)    @Query("UPDATE semantic_facts SET valid_to = :now, superseded_by = :newId WHERE id = :oldId AND valid_to IS NULL")    suspend fun supersede(oldId: Long, newId: Long, now: Long)    @Query("UPDATE semantic_facts SET is_deleted = 1 WHERE id = :id")    suspend fun softDelete(id: Long)    @Query("SELECT COUNT(*) FROM semantic_facts WHERE is_deleted = 0")    suspend fun count(): Int}